,0],["FAJA PORTA GEL FRIO-CALOR","BODY CARE",25000.0,0,0,1,0],["ANTIFAZ GEL RELAX FACIAL","PUMP GEL",20000.0,0,0,0,9],["PROTECTOR BUCAL T.G","BODY CARE",5000.0,0,0,3,1],["PROTECTOR BUCAL T.CH","BODY CARE",5000.0,0,0,4,1],["GUANTES DEPORTIVOS T.S","BODY CARE",28000.0,0,0,0,1],["GUANTES DEPORTIVOS T.L","BODY CARE",28000.0,0,0,0,1],["GUANTES DEPORTIVOS T.XL","BODY CARE",28000.0,0,0,0,1],["ANDADOR ALUMINIO CON RUEDAS Y ASIENTO","DEMA",152000.0,0,0,0,0],["ANDADOR ALUMINIO SIN RUEDAS","DEMA",100000.0,0,0,0,0],["ANDADOR PLEGABLE TIJERA","DEMA",145000.0,0,0,0,0],["SANDALIA POST QUIRURGICA CH","BODY CARE",48000.0,0,0,1,1],["SANDALIA POST QUIRURGICA GRA","BODY CARE",48000.0,0,0,1,2],["SANDALIA POST QUIRURGICA MED","BODY CARE",48000.0,0,0,1,1],["BASTÓN TRIPODE","DEMA",47000.0,0,0,0,0],["PELOTAS PARA MANO REDONDA","DEMA",8000.0,0,0,0,0],["PECHERA DE SEGURIDAD","DEMA",42000.0,0,0,0,4],["ANDADOR SIN RUEDAS","",155000.0,0,0,0,0],["CHATA PLASTICA","",10000.0,0,0,0,0],["ORINA DUAL","",6000.0,0,0,0,0],["CASCO FRIO CALOR","BODY CARE",32000.0,2,0,2,2],["MUÑEQUERA GEL FRIO CALOR T.U","BODY CARE",23000.0,4,0,6,2],["CODERA GEL FRIO CALOR T.U","BODY CARE",32000.0,4,0,3,4],["RODILLERA GEL FRIO CALOR","BODY CARE",45000.0,2,0,3,0],["TOBILLERA FRIO CALOR","BODY CARE",30000.0,0,0,0,2],["ANTIFAZ FRIO CALOR","BODY CARE",18000.0,0,0,0,1],["CERVICAL FRIO CALOR","BODY CARE",42000.0,0,0,0,2]]$p$::jsonb)),
ex0 as (
  select x->>0 dn0, x->>1 mn, (x->>2)::numeric v0,
         (x->>3)::int t,(x->>4)::int p,(x->>5)::int m,(x->>6)::int o
  from payload, jsonb_array_elements(j) x
),
ex as (
  select mn,
    case when mn in('S','M','L','XL') and dn0 in('ZEBRA','EMPIRE','MULTILOG','TECHNORUN','AIRCHANNEL')
         then 'MEDIA RUNNING '||dn0||' T.'||mn else regexp_replace(dn0,'^[.]+','') end bdn,
    case when mn in('S','M','L','XL') and dn0 in('ZEBRA','EMPIRE','MULTILOG','TECHNORUN','AIRCHANNEL')
         then dn0 else mn end bmn,
    case when mn='RUN UP/MARATHON' and dn0 like 'REMERA %' then 29000 else v0 end v,
    t,p,m,o, dn0
  from ex0
),
prod as (
  select id, upper(regexp_replace(descripcion,'\s+',' ','g')) dn, upper(btrim(coalesce(marca,''))) mn
  from marathon.productos
),
j as (
  select distinct on (ex.dn0,ex.mn) ex.*, p.id prod_id
  from ex join prod p on p.dn=ex.bdn and (p.mn=ex.bmn or ex.bmn='')
),
actor as (select user_id uid from marathon.app_users where active and role='ADMIN' order by created_at limit 1),
upd as (
  update marathon.productos pr set precio_venta=j.v
  from j where pr.id=j.prod_id and pr.precio_venta is distinct from j.v
  returning pr.id
),
mov as (
  select producto_id, sede,
    sum(case tipo when 'STOCK_INICIAL' then cantidad when 'AJUSTE_POSITIVO' then cantidad
                  when 'AJUSTE_NEGATIVO' then -cantidad when 'VENTA' then -cantidad else 0 end)::int qty
  from marathon.ortopedia_operaciones group by producto_id, sede
),
deltas as (
  select j.prod_id, s.sede, s.target - coalesce(mv.qty,0) delta
  from j cross join lateral (values('TERMINAL',j.t),('PARQUE',j.p),('MARATHON',j.m),('ORTOPEDIA',j.o)) s(sede,target)
  left join mov mv on mv.producto_id=j.prod_id and mv.sede=s.sede
),
ins as (
  insert into marathon.ortopedia_operaciones
    (id,fecha,hora,tipo,producto_id,sede,cantidad,importe_total,precio_unitario,created_by,updated_by)
  select 'ORT-'||gen_random_uuid(), current_date, localtime,
    case when delta>0 then 'AJUSTE_POSITIVO' else 'AJUSTE_NEGATIVO' end,
    prod_id, sede, abs(delta), 0, 0, (select uid from actor), (select uid from actor)
  from deltas where delta<>0
  returning 1
)
select (select count(*) from upd) as precios_actualizados,
       (select count(*) from ins) as ajustes_stock;

commit;
